local Advisor = _G.CoAAnalyticsAdvisor

-- Données publiques collectées le 9 août 2026. Ce fichier complète les
-- profils de guide existants sans remplacer les modèles quantitatifs issus
-- de DataProbe. Les builds sont des bases de progression vérifiées sur les
-- arbres publiés ; ils ne prétendent pas être une variante de tournoi.
local GuideProfiles = Advisor.GuideProfiles
if not GuideProfiles then return end

GuideProfiles.research = {
    source = "https://ascensionsidekick.com/",
    collectedAt = "2026-08-09",
    profileCount = 70,
    buildHub = {
        source = "https://coabuildhub.com/",
        method = "public-search-index",
        indexedClasses = 19,
        indexedProfiles = 63,
        indexedBuilds = 100,
    },
    buildValidation = {
        profiles = 70,
        abilityPoints = 26,
        talentPoints = 25,
        structuralErrors = 0,
    },
    limitations = {
        "Un seul build de progression est publié par spécialisation.",
        "Les variantes PvE/PvP restent déduites des priorités et infobulles.",
        "Les effets d'objet non chiffrés exigent une vérification manuelle.",
    },
}

local function SplitPriority(value)
    local result = {}
    value = tostring(value or "")
    local start = 1
    while true do
        local first, last = string.find(value, " > ", start, true)
        if not first then
            local tail = string.sub(value, start)
            if tail ~= "" then result[#result + 1] = tail end
            break
        end
        result[#result + 1] = string.sub(value, start, first - 1)
        start = last + 1
    end
    return result
end

local specializationAliases = {
    ["Venomancer:Rot"] = { "Venom" },
    ["Primalist:Wildwalker"] = { "Primal" },
    ["Primalist:Grovekeeper"] = { "Life" },
    ["Runemaster:Engravement"] = { "Runic" },
    ["Runemaster:Glyphic"] = { "Arcane" },
}

local function Add(className, specializationName, research)
    local profile = GuideProfiles.FindByNames(className, specializationName)
    if not profile then return end

    research.collectedAt = GuideProfiles.research.collectedAt
    research.buildVerified = true
    research.buildContextConfidence = "medium"
    profile.research = research
    profile.secondarySource = research.source
    profile.analysisConfidence = research.confidence
    profile.recommendedBuild = research.build
    profile.rotation = research.rotation
    profile.weapons = research.weapons
    profile.contentTiers = research.tiers
    profile.strengths = research.strengths
    profile.weaknesses = research.weaknesses
    profile.researchPvePriority = research.statPriority.pve
    profile.researchPvpPriority = research.statPriority.pvp

    local aliasKey = className .. ":" .. specializationName
    profile.specializationAliases = specializationAliases[aliasKey] or {}
    if GuideProfiles.AddSpecializationAlias then
        for _, alias in ipairs(profile.specializationAliases) do
            GuideProfiles.AddSpecializationAlias(profile, alias)
        end
    end
end

local function SetGear(className, specializationName, advice)
    local profile = GuideProfiles.FindByNames(className, specializationName)
    if not profile or not profile.research then return end
    profile.research.gearAdvice = advice
    profile.gearAdvice = advice
end

local function SetBuildHubEvidence(
    className,
    specializationName,
    buildCount,
    indexedRole
)
    local profile = GuideProfiles.FindByNames(className, specializationName)
    if not profile or not profile.research then return end
    local evidence = {
        buildCount = tonumber(buildCount) or 0,
        indexedRole = indexedRole,
        source = GuideProfiles.research.buildHub.source,
        method = GuideProfiles.research.buildHub.method,
    }
    profile.research.buildHub = evidence
    profile.buildHubEvidence = evidence
end

