    weapons = {
        style = "Ranged", main = "Ranged weapon",
        off = "—", ranged = "Ranged",
        note = "Ranged weapon — Reclamation requires one.", confidence = "high",
    },
    tiers = { dungeon = "A", raid = "A", arena = "A", battleground = "A" },
    pve = { score = 12, note = "high throughput ceiling" },
    strengths = { "Spirit Shock silences and interrupts, Hex of Malice spreads through Shadowflare, and Hex of Death cuts a target's healing received via Malefic Arrow. You shut a target off, not just damage it.", "Shadowstalker clears all harmful effects and boosts speed for a clean disengage. Frenzied Spirits and Spiritual Devotee convert banked Spirits into a self-heal and a steady mana refund, so you recover between fights without a heal spell.", "Reclamation, Malefic Arrow, Spirit Glaive and a Spirit-fueled Spirit Eclipse that explodes each Spirit on impact, with a pack of Serpent Wards from Call of Sseratus and The True Spirit behind them. This threatens real sustained damage." },
    weaknesses = { "Shadowstalker wipes harmful effects on its own timer and that is the entire answer to CC. No on-demand stun or fear break, so a stunlock opener landed while it is down turns off every reset you have.", "The engine needs hits landing to keep the Spirit stack turning. Deny you the time to bank Spirits and your Spirit Eclipse damage and your Spiritual Devotee mana return choke at the same moment.", "Group healing exists and it is light. Brew Lobber auto-tosses brews across the party, Brew Splash spreads brew healing near your target, and the class pool adds Healing Ward. This is still a ranged-DPS tree and cannot stand in as a group healer." },
})
