    strengths = { "Tyrannical Resolve ignores damage for a window and pays out in Felfire, Demonic Will cuts physical damage and heals, and Bulwark of Azzinoth reduces damage taken during Inner Demon. Dark Lord sits on top above 75% health. Nothing bursts through that stack.", "Betrayer and Tyrannical Resolve pull threat and enrage your group off dodges. Infernal Whipcrack enrages allies for reduced damage taken and haste, Eye of the Tyrant hands out party haste, and Doomscarring scars enemies to raise ally attack power.", "Demonic Will heals on damage, Burning Hatred leeches in melee, Hateforged Barrier absorbs and regens, and Grommash's Folly heals off crits during Inner Demon. Long brawls rarely need a healer." },
    weaknesses = { "Damage is modest. You win by not dying, not by killing. Solo kills crawl.", "The defense is anchored to dodge and parry: Illidari Training, Burning Commander's armor and magic resist off dodge rating, Nether Disciple, Vengeance Is Mine. It only ramps while something is meleeing you, so ranged and casters sidestep most of it.", "Resource income comes from being hit, through Illidari Training's dodge-to-Energy and Demonic Fortitude's Felfury off damage taken and avoided. Stop being the focus and your Energy and Felfury dry up right when you want to fight back.", "Felfury overcaps. Twin Slice, Felrend, Demonic Will and Bane of Betrayal each add 1 and Burning Hatred dumps 6, while Carve, Sargeron Smite, Sunder and Inner Demon are all you have to spend it on. Extended fights waste resource.", "Sustain hangs on channeling Carve, your biggest heal window through Straight to the Nether's leech and Demonic Will's heal-on-damage. A knockback or hard stun cuts the channel and your healing with it, which is why anything that displaces or stuns, Scarlet Crusade especially, feels so bad." },
})
