    weaknesses = { "No stun, root, snare, or fear anywhere in the kit. Control is Guard Strike's interrupt and school-lockout plus the Chains of Darkness pull and taunt, so you can grab attention and briefly shut a caster's school, never pin a kiting target in place.", "Noctis Blade is a melee strike, so the self-heal only lands while you are on the target. Against ranged and caster pressure you cannot stick to it does nothing, and that is exactly the damage most likely to kill you.", "Gaze of the Black Knight is one long-cooldown panic button, so you get roughly one real group-save per fight. Misjudge it, or have it down, and you and your ally have no group mitigation at all." },
})
