    strengths = { "Suffuse scales off Stamina and defense and Shieldgore's Demonfire generation pays for it. Sacrificial Circle burns your active imps as a backup emergency heal and leaves a Soul Furnace absorb behind. Sustained pressure does not out-damage that.", "Brimstone Buckler summons imps off blocks, Demonic Bulwark adds critical block, and Curse of Xoroth feeds a Black Shield absorb that Demon's Blood pumps through Hellwrath. Imp Aura, Imp Guards and Hellsmelted Armor cover magic as well as melee.", "Chains of Xoroth slows an area then pulls at the end, Call: Hellfire Abyssal leaves something attacking, and Legion's Presence buffs ally damage. Demolisher's Flesh Hook and Chainwhip taunt on top. You change the fight around you, not just your own health bar." },
    weaknesses = { "No external healing anywhere. Suffuse, Sacrificial Circle and Forgefiend's Bulwark's Enrage all target the Knight and nobody else, so a duo partner lives on your peels, never on your heals.", "No anti-CC or CC-break in the ability list. A stunlock, fear, or sap chain turns off Shieldgore and Suffuse at once, since nothing casts while controlled.", "Shieldgore and Brimstone Buckler both key off a shield, locking you into 1H and shield. The identity is block and mitigation first, so against a two-hand physical bruiser the damage gap is real. You swing fights through survivability, CC and utility, not damage races." },
