    pve = { score = 17.5, note = "brings combat rez, raid haste; moderate throughput ceiling" },
    strengths = { "Keeping the Oath staggers and delays damage, Battlepriest and Light's Ward cut magic damage, and the Untainted and Staffguard absorbs sit on top of Benediction and Condemn self-heals. In an extended skirmish you do not die.", "Tome of Light shields for 100% of max health and Staffguard and Untainted absorb repeatedly, which answers burst windows. Disciplined Mind's dispel and Barrier of Light's healing boost extend that to the party. Testament of Hope summons mirror copies that fight at your side and cut your damage taken.", "Sacred Swing and Reckoning deliver real AoE cleave, Absolution's AoE taunt peels attackers off a partner, and Barrier of Light redirects ally threat onto you. Messy BG scrums are where this is strongest." },
    weaknesses = { "No interrupt in the spec line. Covering it costs a class-kit pick on Divine Force, a stun-leap whose spell-lock only works on non-player casts. No dispel-all and no magic-immunity button, so once Tome of Light and the absorbs are spent you tank the next chain raw.", "Sacred Swing requires a recent dodge or parry, so against pure ranged attackers or while CC-locked your Oath generation stalls and takes your damage and your healing with it.", "Every burst-heal answer is cooldown-bound. Benediction wants banked Oaths to hit hard, Temple Guardian's charge-heal sits on a charge timer, and Testament of Faith and the class kit's Libram of Tenacity each live on their own cooldown. Back-to-back heal checks outpace what you have available." },
