    pve = { score = 20, note = "brings combat rez, raid haste; high throughput ceiling" },
    strengths = { "Stacked Oaths run at once: an extra target struck, more damage and healing, more crit. Protect the Oath Chain and everything you do scales together, rather than one big button getting bigger.", "Argent Blade heals for the damage it deals and Titanfall makes Titanstrike heal for twice its damage, folding recovery into the rotation. On a big pull Libram of Grace turns every damaging ability into party healing.", "Interdict silences a target and locks Undead and Demons out of healing. Crusader's Brand pins a runner so they cannot flee, mount, or speed away, and reveals them through stealth. Divine Charge gives the party a mounted speed burst outdoors that does not break on casting." },
    weaknesses = { "The healing is incidental self-heal off Argent Blade and Titanstrike, not throughput, and it cannot cover a group. Worse, Testament of Fortitude and Testament of Strength both apply Sacred Restraint for a minute, blocking further Testaments, so the defensive and offensive ones compete directly.", "Everything rides one timer. Let the Oath Chain lapse and all three stacked Oaths vanish together and you rebuild from zero, so a long run between packs, a kite, or a CC chain costs far more than its seconds. The finisher kit is 2H-weapon-gated.", "Righteous Lunge is the only real engage. Divine Charge is an outdoors-only party movement cooldown, not a targeted gap-closer, and there is no blink or escape, so sustained kiting shuts off your damage and the self-heals it feeds. No dispel-all, no magic-immunity button." },
})
