    pve = { score = 10.5, note = "moderate throughput ceiling" },
    strengths = { "Shield of the Ages stacks damage reduction and a healing bonus off crits, and Aeon of Protection's absorb layers onto Time Out!'s damage cut. Bursting you or your partner takes real effort.", "Buy Time's AoE stasis freeze swings a fight on its own, with no ally CC needed to set it up. The Vast Infinite pools and heals party damage as a raid-wide save.", "The four Aeons and Fabric of Time reshape Epoch into burst, absorb, HoT, or cheap-cast healing. You retune to the fight instead of playing one pattern." },
    weaknesses = { "Every strong tool sits on a cooldown and costs mana: the four Aeons, Buy Time, Shield of the Ages, Temporal Anomaly. Dump them at the wrong moment and the next stretch is rough. Timeguard and Infinity's cooldown-free Infinite Shield are single-target stopgaps eating Ability Essence picks.", "Buy Time's stasis makes the target invulnerable, so anyone low you freeze walks away alive. Nothing in the kit stops a determined physical stunlock either.", "Continuum Restoration and Displacement only handle magic and roots or snares. There is no real CC-break, so a chain-stun or silence landing while your cooldowns are down kills you." },
})
