    weaknesses = { "No on-demand self-heal, no HoT, no life-drain. Recovery is all conditional: Cryoshroud's ice-tomb heal needs Lich Form and only fires below a third of your health, Phylactery's Shade has to be pre-placed, Vampiric Aura drips only below half. Pressure that never trips those thresholds leaves you nothing to press.", "Mana, Runic Power, Life Force minion upkeep, several separately-timed freeze cooldowns. Sequencing the burst combo has a high floor.", "No gap-closer, no escape, no stun. Your peels are offensive freezes that get resisted or trinketed, and the backups are all defensive: Phylactery's Shade, Cryoshroud's ice tomb, Bone Tithe's shield castable while stunned. They buy seconds. Nothing moves you, and you are still a caster with a cast bar." },
})
