    weaknesses = { "No teammate heal, and no root, stun, silence, or interrupt to lock a target for your team. The substitutes are indirect: the Corpse Wagon damage aura, Create Bone Reliquary as a once-a-minute click heal, Call of The Scourge as a battle res, and Mass Grave's fear, which only works on Humanoids.", "The Life Force and pet economy is fragile and management-heavy. Animate pets are short-duration and Raise: Ghoul pets are capped by a pool you grow through the Summoning passives. AoE cleave or CC that kills the pets takes your damage and your self-healing with them.", "Your damage and your Runic Power both come from the pets, fed by the Crypt Swarm channel and Command spells. Zone them, kite them off, or delete them and you are down to Crypt Swarm and cheap Animate pets until the army is rebuilt." },
