    strengths = { "Spirit of the Phoenix is a cheat-death once per 10 minutes, sitting behind Inferno Barrier absorbs and Shielded by Flames shielding on crits. Finishing you off is one of the hardest jobs in the game, and that is the backbone of 1vX.", "Cleansing Flames heals your side and hits theirs in one frontal cast. No coordination required.", "Burn Impurities cleanses magic and disease, Neltharion's Resolve wards the party against a fear, and Warmth passively heals your lowest ally. Roaring Pyre, Phoenix Egg and Kael's Command blanket the group in passive healing. None of it needs a partner to set up." },
    weaknesses = { "Kindle, Cinderheart and Cleansing Flames are all cast-time and fold to an interrupt chain. A rogue on you shuts them off before your absorbs can bail you out. Only Ember Touch, an instant Ember-spender, keeps flowing through a kick.", "Flame Step is instant, dashes 20 yards and frees you from stuns and bonds, but it is one 20-second cooldown and your only escape. Caught with it down under a stunlock you are on Inferno Barrier absorbs and the once-per-10-minute Spirit of the Phoenix. Everything else is peel.", "Inferno Barrier, Phoenix Dive and the Roaring Pyre and Kael's Command healing zones are all cooldown-gated, and once spent sustain falls back to cast-time heal spam. Phoenix Egg is the exception, with no cooldown beyond the one-active-Phoenix cap, so it stays up as passive healing." },
