    strengths = { "Trading hits is how you heal. Blade of Yogg-Saron's on-hit heal, Shadow Pennant, and As The Prophecy Foretold's crit mana refund carry you through most 1v1s and 1vX without outside help.", "Abyssal Covenant soaks an ally's damage and turns your damage into their healing. Dark Veil channels through stuns and silences while stacking a shield on you and an ally. Few healers protect a focus target this well.", "Malevolence and Gaze of C'Thun hit an enemy and heal allies off the same cast. You apply pressure instead of standing there supporting, which is what wins a sloppy skirmish.", "Whispers of N'zoth, amplified by the Shadow Words talent, is an all-stats party and raid buff in the Blessing of Kings mould, with Whispers of C'thun and Whispers of Y'shaarj as spell power and mana regen alternates. Void Resilience's shadow-resistance aura runs alongside." },
    weaknesses = { "You juggle mana and Insanity at once, most spells costing a share of base mana while Insanity builds and spends against the Total Madness cap. Misplay either one and both your damage and your healing stall.", "No interrupt at all. Mass Nightmare only interrupts non-player spellcasting and Corrupt Mind is a fear, so a caster who has to be stopped is your group's problem. Devour Magic and Devour Curse are single-target, roughly a second to cast, and expensive.", "Dark Veil and Satiate are channels. The instant, guaranteed-crit Eldritch Mendings that answer a spike need Eldritch Eye or a Malevolent Power proc to be up, and with those down a sudden burst window outruns your raw throughput.", "Malevolence is a 5-yard spell that fails outright if the target dies or leaves range, and Blade of the Empire needs melee too, so most of your healing happens standing in cleave and stun range. It works while moving, but holding a target in range is its own skill." },
})
