    strengths = { "Chosen of the Moon's flat physical reduction and AoE taunt, Moonlit Bulwark's stun-proof mana shield, Blanket of Stars' shield-gated block wall and Astral Reconstitution's damage-to-mana conversion all stack, with Coalesced Resilience and party-wide Shrouded Stars underneath. You eat focus fire far longer than melee should.", "Avoided attacks call down Moonflares for AoE Arcane damage that cannot be dodged, blocks seed Scattered Stars through Nebula, and parries refund Energy while punishing the attacker via Dancing in the Moonlight. Tanking well is how you deal damage.", "Parries refund Energy and Celestial Cleave, and Starsweep's star consumption and Astral Reconstitution refund mana per hit. Font of Magic trickles health back as you spend, so you rarely stop swinging." },
    weaknesses = { "No direct heal, no battle-rez, no true cleanse; Vial of Moonwell Water strips crowd control, not poison or magic. You live on mitigation cooldowns and Starbound's healing bonus. The only heal buttons are Touch of Moonlight and the Moonwell Tides talent, a sizable but occasional emergency.", "No charge, no gap-closer of any kind. Chosen of the Moon's taunt drags the target to you but never moves you, so ranged classes that respect your cooldowns kite you.", "The payoffs are proc-gated. Vengeance of Elune needs a real parried attack, Nebula seeds stars off blocks, Star Pupil wants damaging crits. Starslip sheds slows and roots and Celestial Impact stuns, but no hard-CC break exists in the spec, and the only one, Vial of Moonwell Water, costs a class pick." },
})
