    pve = { score = 16.5, note = "brings mana replenish; moderate throughput ceiling" },
    strengths = { "Getting hit builds Rage and Exposed Flesh, which pay out as mitigation and heal dumps: Regrow Exoskeleton, the Barbed Stinger and Expulsion shed, Beetle Form's Reformed heal, Harden, Lifeblood turning damage taken into healing. Charm of Warding and Carapace Regeneration proc underneath. Focus fire does not wear you down.", "Barbed Stinger's throw-and-rip pull drags a fleeing enemy back or yanks whoever is on your healer. The Nature vulnerability it applies through Shadra's Gift softens that target for the whole team.", "Venomtip Poison, Expulsion and Locust Swarm blanket a fight in DoT, leech and cleave, and Slimy's Beetle Slime pools spread by Carapace Crash hold ground. None of it needs a healer behind it.", "Spider Form shifts for move speed, Skitter dashes on three charges, Chitin Rush closes gaps and Molt bursts. You chain-pull and reposition far faster than most tanks." },
    weaknesses = { "Every spec-line heal points at yourself: Regrow Exoskeleton, Beetle Form's Reformed shed heals, Regenerative Properties, Protogenesis, Carapace Regeneration. Green Salve and Shadra's Balm heal an ally if you spend the picks, but they are spot patches. You cannot keep a duo partner up.", "Unshed Exposed Flesh stacks raise your physical damage taken, so mistiming the shed turns your core defensive mechanic into a liability. Single-target burst stays mediocre as the price of all that survivability.", "Harden, Carapace Regeneration and avoidance cover physical damage and do little against magic burst. The control is real, Nullifying Toxin's interrupt and Impale's uncapped line stun, but it lives in cooldowns and Spider-Form weaves, not the Beetle-Form tank loop. A caster train that kites you with Harden down grinds you out." },
})
