    pve = { score = 16, note = "high throughput ceiling" },
    strengths = { "The Soul Harvest cascade heals off your own fragment generation and Lamenting converts Ghostly Weapon's Frost damage into healing. Spiritual Reflexes fires Soul Harvest when you dodge below 35% health. No dedicated heal spell anywhere, and it still heals like this.", "Limbo covers magic burst and Shade drops you into improved stealth while removing all movement-impairing effects. Two different outs, and Sepulchral Renewal resets both.", "Spectre Stride closes, Shade, Underwalk and Beyond the Veil give speed and water-walking, and Ghost Claw with Deathchaser's sub-20% reapplication holds a target through the kill." },
    weaknesses = { "Death's Presence, a static party damage buff, is the entire party toolkit. A partner under pressure gets no heal, no shield and no CC-break from you, only whatever pressure you put on their attacker.", "Limbo and Shade are finite cooldowns. Spend both and there is a dead window with no CC-break left between you and the next burst.", "Soul Fragments into Reaped Souls into Soul Infusion into Reliquary of the Lost and Soulslam: every step needs hits landing in melee. A kite, root, or slow stalls damage, self-healing and Runic Power together." },
})
