    weaknesses = { "No healing and no damage-reduction cooldown anywhere in the kit. You cannot mitigate or out-heal a single hit, so being caught in melee is usually fatal. Burst and kite or lose outright.", "The glyph chain runs Frost to Flame to Arcane and all three stages have to be tracked. Mistime the sequence and the glyph payload is wasted.", "Most abilities cost a percentage of base mana and the big cooldowns take large chunks. Focusing Crystals' partial regen is your only in-combat relief: no mana-return burst, no mana-burn.", "The control is strong on paper and clunky in play. Glacial Rune arms after about a second, Silencing Rune has its own delay, Cryobrand is a short-range single-target freeze, and repositioning is Warpdagger's throw-then-teleport, not a Blink. None of it reacts fast enough to gap-closing melee." },
