        role = "Ranged DPS (melee-range spellstrike hybrid)",
        playstyle = "Despite being flagged Ranged DPS, Runic actually fights at melee range as a spellstrike hybrid — Runeblade and Fist of the Ancients trigger Weapon Engravings while Primordial Strength converts a slice of AP and Agility into spell damage/hit/crit, so it plays like a melee class with a caster's toolkit layered on top. Solo it opens with Runic Brand into Fist of the Ancients cleave, sustains mana off Leystone Springs' auto-attack procs, and leans on Granite Resolve/Guarding Rune/Granite Shield to tank through pulls; in groups it brings Guarding Rune's magic-damage barrier and Leyline Disturbance's haste buff alongside strong single-target and cleave damage.",
        keystone = "Primordial Strength (r2,c10, L20 passive) — the AP-into-spell-damage/Agility-into-hit-crit conversion that defines Runic's melee-range spellstrike hybrid identity.",
