    strengths = { "Leyline Disturbance hands the party a haste aura and shaves stun duration, and Guarding Rune barriers them against magic damage. You do all that while bursting with Primordial Blast, Fist of the Ancients, Runic Brand and Zenith.", "Ley Power ramps damage per nearby enemy and Runic Explosion into Wild Steam pays you for being surrounded. Being outnumbered is the shape this spec wants.", "The Earth Elemental Carving heal-over-time, Granite Shield under Runic Tattoos: Earth, and Water-Carving's mana return keep you in the fight without a dedicated healer, with Protective Warding cooling Rune of Guarding on top." },
    weaknesses = { "No repeatable on-demand heal for yourself or an ally. Sustain is RNG procs, the Earth Elemental Carving heal-over-time and Granite Shield, and RNG does not out-heal sustained pressure.", "Damage and utility come in windows rather than a stream. Primordial Blast is on cooldown, Runic Brand needs its mark to stack and detonate, and Zenith, Runic Tempest and Fists of Power are windowed. With those down mid-fight there is little left to press.", "Defense is Guarding Rune plus RNG mitigation procs. Granite Resolve adds an on-demand physical damage reduction usable while stunned, but there is no true absorb and nothing against magic, so once Guarding Rune drops spell pressure finds a soft target. Escapes are class-kit picks." },
