    strengths = { "Smolder, Fracture, Hoarfrost and Hurricane feed a resource-returning Runeblade proc chain, so single-target melee damage pays for itself. Zenith and Primordial Fury are the burst layer on top.", "Ley Lock is a hard interrupt, instant under Battle Engravings. Magebreaker self-dispels and Fracture burns mana off enemy casters.", "Primordial Fury cleaves your strikes into extra enemies and Turbulence's AoE zone pays you for being surrounded. Phase Out with Rift Clones is a strong juke and disengage." },
