SetGear("Barbarian", "Brutality", "Weapon is flexible. It plays naturally dual-wield, since Smash and Barbaric Whirl both strike with both weapons, and a competitive one-hand build exists. A two-hander also works, and Battering Ram rewards a 2H mace or axe with extra Armor penetration. Run whichever your drops favor. Either way a big-hitting main weapon drives Brutal Swing, Decapitate, Maximum Carnage and Storm of Steel. Armor: many players run leather for the baseline Agility, though heavier armor is fine if you would rather stand in the clump and eat hits. Stat priority: cap Hit/Expertise first (Pure Power adds expertise) so specials stop missing and getting parried. Then Agility as the primary attribute, since Ancestral Might turns Agility into attack power and Body Builder converts Agility into Strength, so it scales AP two ways. Strength is a strong secondary that scales hard off external buffs. Its AP conversion is large, so beg for Strength/attribute buffs in a group. Crit (feeds Anger Issues' Carnage resets, Savage's crit-damage payoff, and crit bleeds like Headlopper) and Armor Penetration both rank highly over Haste, and several top players value Armor Pen above Crit. Keep Stamina over Defense/Resilience for the 1vX goal, since your survival is a percentage-of-health regen loop that scales with your health pool.")
SetGear("Barbarian", "Headhunting", "Physical-only kit with no offensive spellcasting, so ignore Spell Power/MP5 entirely. Stat priority: Agility first. It feeds the Attack Power/Ranged Attack Power that Puncture Wounds/Berserker Rush and your Agility-scaled Born in Blood all key off, plus crit, and Power Tosser makes Throw Weapon itself scale with Agility. Then Hit/Expertise to a reasonable floor (Strong Arm adds hit) so your ranged openers and melee weave land. Then Crit (drives Furious Berserker's Born in Blood grants, Berserker's Enraged crit buff, and Puncture Wounds bleeds) and Haste (faster Throw Weapon/Axe Twirling casts). Then Armor Pen, which rewards the Berserker Axe/Guts Splatter armor-shred windows. Past a point, put solid Stamina above raw offense, since your Agility-scaled Born in Blood heals bigger off a larger pool. Some Resilience and Defense round out PvP survivability given the melee-adjacent exposure. Weapon: a one- or two-hand melee weapon. No thrown slot is required, since your thrown attacks are abilities, not an equipped Thrown item.")
SetGear("Barbarian", "Ancestry", "Melee weapon user built around Agility/AP scaling, with a build-defining option. Thane's Guard grants shield proficiency and turns a shield from a pure mitigation piece into an offense steroid: increased attack speed and more Armor contribution from the shield itself. That's the intended 1H+Shield setup, trading a little raw stat-stick damage for speed and the survivability of an actual shield. Thane's Grip is the alternative, wielding a two-handed weapon in each hand at a damage penalty. Stat priority: Agility (feeds AP scaling, Honored Ancestor scaling, and your Ancestral Whirl damage) > Attack Power/Strength (Keg Smash and Breath of the North both scale directly off AP) > Haste (more swings = more Ancestral Combat procs and faster Ale of the God-King/Keg Smash cycling) > Crit (feeds Frozen Blades and Cold Brew's Fill Level generation on Frost crits) > enough Hit/Expertise to stop missing/being parried.")
SetGear("Witch Doctor", "Voodoo", "No tank or melee signal anywhere in the kit. This is an Intellect/Spirit caster build, so treat it as Int/Spirit caster gear with a caster weapon (staff or 1H + off-hand) carrying Spell Power/Intellect. Stat priority: Intellect (mana pool, and War Golem's absorb scales directly off your Intellect) → Spirit (this spec keys off Spirit unusually hard: Voodoo Power converts it into spell damage and hit, Bad Juju and Hexfire scale off it directly, and Loa Spirits/Staff of the Coven/The Price of Power all pump it) → Spell Power (the scalar behind almost every damage ability) → Haste (the kit self-grants haste via Hexplosion on crit and Malicious Golems on War Golem summon, so haste compounds hard here) → Crit (feeds Spirit generation, De Other Side, and Juju Spirits' per-Spirit crit) → MP5 (costs run several percent up to ~25% of base mana per cast, so regen matters) → Hit (Staff of the Coven and Voodoo Power already grant some).")
SetGear("Witch Doctor", "Brewing", "Treat this as a caster-support gear set. Caster-itemized gear, prioritizing Spirit and Spell Power above raw armor value. Weapon slot is a caster weapon (staff or 1H + off-hand), low priority relative to stats since nothing in the kit scales off weapon damage. Stat priority: Spell Power first (drives Loa's Brew, Potion Toss, Mojo Beam, Splash Potion, and Voodoo Cauldron scaling) and Spirit close behind (it appears directly in Loa's Brew, Potion Toss and Splash Potion, and Spirit Healer converts it into healing power and spell crit). Then Haste (shortens Loa's Brew's cast and stacks with Sen'jin's Presence's and Brewmaster's brew-cast-time reductions) roughly even with Crit (Presence of the Loa raises your crit and It's Da Mojo lets Mojo Beam crit). MP5 is a sustain stat given how many buttons cost a percentage of base mana, and Mojo Addiction pads the pool. Resilience serves the don't-die-when-focused goal, since Brewing's only real mitigation is the Cauldron Base/Ingredient layer plus Voodoo Cauldron rather than a personal immunity cooldown.")
SetGear("Witch Doctor", "Shadowhunting", "Weapon: needs a Ranged Weapon, and it's mandatory. Shadowhunter grants the auto-shot, and the weapon carries the bulk of the kit's scaling (Reclamation, Malefic Arrow, Spirit Glaive, Spirit Eclipse all read ranged attack power). This is a ranged-weapon spec, not a caster or dual-wielder. Armor: Agility-hybrid, so treat as the class's light/agility tier and itemize for Agility first. Stat priority: this gears like a hunter. Raw Attack Power leads, because nearly every ability reads ranged attack power directly (Reclamation, Malefic Arrow, Spirit Glaive, Spirit Eclipse), and Sen'jin's Apprentice pours your Intellect and Agility into ranged attack power on top (Agility also into spell power, and Loa's Strength adds Agility plus Nature/Shadow damage). So: Attack Power > Critical Strike (the kit is crit-hungry, since Eye of Kimbul applies on crit, and Umbral Glaive and Frenzied Spirits' crit-and-heal all pay off it) > Agility (a strong secondary since it converts to attack power and a little crit) > Intellect/Spirit (mana pool and regen for your Jinx and Spirit costs) > Spell Power (a minor scalar covering Voodoo Fire and a few Nature effects, not your core damage) > Hit only until your specials stop missing a boss. Haste is your lowest gear priority. It comes from Shadow Avatar and buffs, and mostly speeds your Serpent Wards via Berserking, not from stacking it on gear. In PvP, Resilience and Stamina come first, then the same Attack-Power/Crit core.")
SetGear("Felsworn", "Slayer", "Dual-wield one-handed melee weapons are mandatory. The off-hand is not a throwaway slot, since Dancing Blades, Slice & Dice and Glaiving all key off off-hand damage. Stat priority: Agility first (nearly every ability scales off it, and Spite/Unbound convert Agility into crit, dodge, and hit) and its Attack Power, then Crit (crits trigger Dancing Blades' off-hand cleave and stack Oblivion, so crit chance multiplies your proc and cleave uptime), then Stamina (raw survivability). Then Haste (more swings = more off-hand procs and faster combo cycling) and Expertise/Hit (a missed or parried Azzinoth's Assault or Glaiving breaks the Felfury flow everything else depends on). Skip Spirit/MP5 entirely (no mana resource) and Spell Power (only Immolation Aura leans on Spell-Fire power, and the kit is overwhelmingly Physical-tagged). Add Resilience for PvP survivability once physical priority is met. Armor Pen is useful but has diminishing returns here. The build already ignores a large share of enemy armor through Bane of Frailty (on-pull), Fel Blades' stacking armor reduction, and Azzinoth's Rage's passive penetration, so treat gear Armor Pen as a bonus, not a stat to over-stack.")
SetGear("Felsworn", "Infernal", "The kit doesn't state an armor proficiency directly, but every damage formula scales primarily off Spell Power, with several nukes taking the greater of Spell Power or Spell-Fire power. Gear and itemize as a caster (staff, or 1H plus off-hand for Spell Power) rather than chasing melee weapon DPS. Stat priority: Spell Power > Intellect (Hidden Power converts a chunk of your Intellect and Spirit into spell damage) > Haste (feeds your Fel Fireball filler cadence and Felfury generation) > Hit up to the cap (Wrath of Sargeras covers part of your spell hit) > Crit (Fel Cannon, Archimonde's Wrath and Nether Spirit all lean on it, and Nether Spirit/Hidden Power make some Spirit worthwhile). Pure melee weapon DPS, Attack Power and Expertise are dead stats.")
SetGear("Felsworn", "Tyrant", "A two-handed melee weapon is the baseline, and Burning Commander lets you dual-wield two-handers, granting extra armor and magic resist scaled off your dodge rating. Stat priority: Stamina first (raw HP pool plus it scales your self-heals, since Hateforged Barrier's absorb scales with Stamina and Hulking Demon turns Stamina into attack power), alongside Agility (feeds dodge and, via dodge rating, your armor/magic resist, and Felblade scales your hits with Agility). Then dodge rating directly, since it's name-checked by Demonic Fortitude, Burning Commander, Pure Hatred and Illidari Training's Energy generation, so itemized dodge is worth chasing. Then Attack Power (feeds both your self-heals and your reduced-but-real damage), then Hit/Expertise enough to land taunts and threat reliably. Crit and Armor Pen are lower priority, since survival stats outvalue raw damage scaling here. Grab Resilience for PvP once base stats are covered.")
SetGear("Witch Hunter", "Boltslinger", "Agility, Hit, Crit and Haste with a Spell Power kicker, since Heartseeking Bolt and Tormentor both scale partly off spell power. Stamina matters too, grounded in having only a conditional execute self-heal. You can't out-heal sustained pressure, so raw survivability counts for more than it would on a pure turret.")
SetGear("Witch Hunter", "Houndmaster", "Ranged mainstay via the musket/gun, since Repulse fires from your musket. Dark Mind converts Intellect into crit rating, so run Agility with an Intellect kicker, plus Hit, Crit and Haste. There's no Vampiric-style sustain to gear around. Stamina matters because your only lifeline is Daredevil.")
SetGear("Witch Hunter", "Black Knight", "2H weapon mandatory (Polearm, Staff, 2H Axe, 2H Mace, or 2H Sword), since Noctis Blade, Grasp of the Undying and Witch Knight all key off a two-handed weapon. Gear weighted toward heavier mitigation, since Dark Chivalry explicitly boosts your Armor contribution from your gear and No Regrets adds Armor while March of the Black King is up. Stat priority: Stamina and Defense first for survivability. Then Parry rating, which scales the damage AND self-heal of Noctis Blade, your main sustain, so it doubles as offense and survivability. This spec wants defensive melee stats, not pure offense. Then Haste (more swings per minute = more Shadowstorm proc rolls), then a blend of Attack Power and Spell Power (Shadowstorm and the Shadow-Brand payload scale off both, an unusual hybrid itemization call), then Hit/Expertise (landing swings and Noctis Blade reliably). Crit and Armor Penetration are low-priority tertiary stats.")
SetGear("Witch Hunter", "Inquisition", "Dual-wield one-handed melee weapons. Dusk Blade and Purifier's Edge both strike with both weapons, and Brooding Hatred boosts off-hand damage. Malice turns Agility into fire spell damage and Intellect into attack power, so run Agility with an Intellect kicker. Crit feeds Burned Alive (crit vs sub-20% targets) and your stacking payoffs, with Hit/Expertise to land the strikes and Haste to cycle the build-and-spend loop faster.")
SetGear("Stormbringer", "Lightning", "Caster gear built around Spell Power, since the kit's scaling damage is entirely SP-driven: Arm of Thorim scales spell power, Volt spell power, Forked Lightning spell power. Priority: Spell Power > Haste (faster casts on Arm of Thorim/Conjure Storm and more generator casts per minute to keep Static flowing) > Crit (feeds Critical Circuit's Static refund on spender crits and Dark Skies' escalating crit chance) > Intellect (mana pool) > Spirit/MP5 (mandatory given how many spells cost a chunk of base mana) > Hit (to land Volt/Arm of Thorim reliably into player-level resistance). Weapon should be a pure caster implement (staff, or 1H + off-hand) with Spell Power as the leading affix. Nothing in the kit calls for melee/physical stats.")
SetGear("Stormbringer", "Wind", "Caster gear, on an Intellect item budget. Single caster weapon: staff, or 1H + off-hand. Everything scales off Intellect and Spell Power: Kiss of the Clouds' absorb explicitly scales with Int, and most damage tooltips scale with SP. Priority: Intellect (mana pool + spell power) > Spell Power > Haste (faster casts/GCD, feeds Tailwind uptime loops and your generator throughput) > Spirit/MP5 (buff/shield/CC spam eats mana, so regen matters over an extended fight) > Crit (Unrelenting Winds adds crit to Gale, and crit also extends Gift of Air on your elemental) > Hit (land your CC and buffs, since a resisted Raging Zephyr is wasted control in a fight you needed it).")
SetGear("Stormbringer", "Maelstrom", "Pure caster gear. Whatever armor class COA assigns to Stormbringer, run one-hand plus offhand or a caster-stat staff. Nothing in the kit scales off melee weapon damage, so don't chase weapon DPS. Stat priority: Intellect (mana pool, and Whirling Maelstrom turns Intellect directly into spell haste) > Spell Power > Hit (to reliably land Torrential Wrath/Brine/Deluge, and Disciple of Thorim also adds hit) > Haste (feeds Stormflow's tick rate) > Crit (Prodigy of Lei Shen lets Stormflow crit, Flow of Wrath adds crit against Drowned targets, Kinetic Energy stacks off Conductive spends, and Hydro Powered amplifies your crit damage), then Spirit/MP5 as a secondary, since every core spell has a flat mana cost and the kit has no meaningful mana-return to lean on. Stack Resilience in PvP gear specifically, because there is no healer-grade self-sustain beyond a modest Stormflow leech to offset incoming damage.")
SetGear("Knight of Xoroth", "War", "Two-handed weapon required, since Gore keys off Polearm/Staff/Two-Handed Axe/Two-Handed Mace/Two-Handed Sword. Go heaviest-armor slot available for a frontline melee, since the kit assumes you're eating hits to fuel Demon's Blood and Demonfire. Stat priority: Strength first (feeds every AP-scaled number, including Sever, Skulltaker and Pestilence of Death's unleash, and Render converts Strength into melee haste), then Crit (feeds Chop Shop, Consuming Blade, Hellfire Striker, and Decimation's crit setup), then Hit/Expertise so your rage generators land. Then Armor Penetration (Absolutism already ignores armor on Meatsaw), then Haste. For PvP, weight Stamina/Resilience over pure damage. The kit's win condition is staying alive long enough to out-sustain via Gorged's lifesteal, since it has no defensive cooldown.")
SetGear("Knight of Xoroth", "Hellfire", "Melee weapon (one- or two-hand) for the melee half of the kit. Burning Power converts a portion of Intellect into Attack Power and a portion of Strength into spell damage, and Cinderblade converts Intellect into crit rating and adds spell hit, so this spec double-dips Str and Int rather than picking one. Prioritize Intellect and Strength roughly evenly for the AP/spellpower/crit conversion, then Hit/Expertise to reliably land Infernal Strike and melee swings, then Crit (feeds crit-scaling talents like To Ashes and Flamewrath), then Haste for faster Rage generation between attacks. Armor Penetration is low priority. The bulk of the damage (Hellmaw, Seeking Flame, Hellstorm, Flames of Xoroth) is Fire/Shadowflame spell damage scaling off Spell Power, not physical AP scaling.")
SetGear("Knight of Xoroth", "Defiance", "One-hand weapon + shield. Shieldgore and Brimstone Buckler, its two best tools, both key off a shield. Stat priority: Strength first (drives Attack Power, and Hellfire Resolve converts a chunk of Strength directly into block rating and hit rating), then Stamina (raw health pool plus a direct scalar on Suffuse's healing). Then Hit/Expertise to make sure Shieldgore/Hellfire Bellows land and aren't dodged/parried, then Crit and Defense/Armor for raw avoidance and block value. Treat Spell Power as a useful secondary stat, not a priority. Shieldgore, Implosion and Hellfire Bellows all have a fire/SP coefficient, so a few hybrid Str/Sta/SP pieces are fine, but don't chase pure caster gear.")
SetGear("Guardian", "Vanguard", "One-handed weapon + shield, and it's mandatory: Pulverize, Ram, Hammer of Kings, Heavy Blow, Brace and Bastion all require a shield or a one-handed weapon. Shieldlord's Strength is the one exception, allowing a two-handed mace alongside a shield. Stat priority: Stamina is unusually load-bearing (Bulwark converts Stamina into both block value and hit rating, and Iron Guardian stacks more Stamina), alongside Strength for Attack Power. After that, Block Rating/avoidance is doubly valuable, since blocking drives Resilient's max-HP bump, Iron Barrier's critical blocks, Paragon and Retaliation's reflect, and Stalwart adds block value + expertise. Then enough Hit/Expertise to land Heavy Blow/Ram/Hammer of Kings reliably (Bulwark also converts Stamina into hit rating), then Resilience for PvP survivability. Crit, Armor Pen, Spell Power and MP5 are all low priority. This kit is mitigation- and proc-driven, not a crit/AP-scaling burst kit, and it has no mana or spellcasting to fuel.")
SetGear("Guardian", "Inspiration", "Confirmed from the kit: a shield (Ram requires a shield) plus a one-handed melee weapon (the melee fillers require a one-handed melee weapon). Sword-and-board, not dual-wield or two-hand. Armor type isn't stated in the kit text itself, but the shield/block-rating design points at the heaviest armor class the Guardian class has access to. Stat priority: Strength first (feeds AP for Ram/Broad Sweep/Ballads/Song of Battle and scales Inspiring Presence's ally-damage aura, and Leading the March boosts AP + Armor) > Stamina (survivability) > Crit (feeds Tempo and Powerful Voice's Ballad crit-chance toward Sound of War) > Defense/Armor plus enough Hit/Expertise to land Broad Sweep/Ram reliably. Agility is a secondary AP source via Dragonslayer. Spell Power and MP5 are dead stats. Everything runs on Energy and Strength/AP, not mana.")
SetGear("Guardian", "Gladiator", "One-handed melee weapon and a shield. Most of the kit's identity abilities (Ram, Pulverize, Raise Shield) require a shield, and the melee fillers (Broad Sweep, Centurion Strike, Spear Throw, Reprisal) require a one-handed melee weapon, so two-handers are off the table. Polearm Training is the one exception, allowing a polearm alongside a shield. Stat priority: Strength first (scales block rating via Shield Training and Bulwark Rush, and feeds Built Different's Str/Sta bump plus Experienced Combatant's AP conversion), then Critical Strike (feeds the Favor crit engine and Axe Training), then Stamina (also feeds block rating and gives flat HP via Built Different). Then Hit/Expertise to cap (landing Ram/Pulverize/Broad Sweep reliably and avoiding dodge losses via Double Duty), then Armor Penetration (Mace Training bumps it further), with Agility as a secondary AP source via Overwhelming Presence. Treat Haste as low priority. It's an energy-capped kit, so more swings without more regen just starves you faster. Value Resilience/Defense highly for PvP survivability given how mitigation- and block-reliant the defense is.")
SetGear("Templar", "Zealot", "Weapon: the core build is a dual-wield/off-hand build. Righteous Lunge, Vindication and Righteous Upheaval all use one-handed melee weapons, and the Zealotry passive explicitly makes your off-hand auto attacks trigger Zealotry, so a real off-hand weapon (not a shield) is mandatory. Bursting Impact even boosts your off-hand damage. Stat priority: gear for ATTACK POWER. Calm Combatant makes your Holy damage scale off attack power, and AP also drives your weapon damage (which is exactly what your Zealotry procs and Righteous Upheaval read) and your auto attacks, so it double-dips harder than Spell Power. Agility first (it gives attack power AND crit, and Martial Paladin scales it up), then flat Attack Power, then Spell Power (the hybrid half of most coefficients), then Crit (fuels Chakra of Power's Energy return and Condemnation), then a little Haste. All of that comes after enough Hit/Expertise to cap, since a missed Oath builder stalls the whole economy. Stamina and Resilience for PvP. MP5 is low priority, since Energy fuels the core rotation and mana only pays for a few utility spells.")
SetGear("Templar", "Oathkeeper", "Weapon: a slow two-hand weapon in the spec's required types (Polearm, Staff, or Two-Handed Mace). Most of the spender kit (Sacred Swing, Reckoning, the Righteous Lunge line, Temple Guardian) is gated on these, and its weapon-damage-% finishers benefit from higher damage-per-swing. Gear: Agility-weighted itemization. Blessed Padding boosts your Armor, and Graceful Fighter (parry from Agility, dodge from Intellect) plus Paragon (Stamina scaled off Agility) mean Agility functions as a core defensive stat here, not a dump stat. Stat priority: Stamina (feeds Paragon's health pool, and directly scales Untainted/Staffguard/Reckoning/Temple Guardian) ≈ Agility (dodge, parry, armor, Paragon Stamina) > Attack Power + Spell Power (both scale the same finishers, meaning Chastise, Benediction and Temple Guardian's heal, so a hybrid stat stick is ideal) > Crit/Haste (faster Energy/GCD cycling) > Hit/Expertise to a reasonable floor > Resilience as PvP effective-health padding given you're the thing being focused.")
SetGear("Templar", "Crusader", "2H weapon only (Polearm, Staff, 2H Axe, 2H Mace, or 2H Sword). This is mandatory for Titanstrike, Righteous Tempest and Argent Blade to even be usable. Stat priority: Agility first, as its primary stat, since Light's Chosen converts Agility into spell power and Intellect into crit rating, so Agility feeds both sides of the hybrid. Spell Power/Attack Power sit close behind, because most finishers and its self-heals scale off a Spell Power + Attack Power hybrid formula. Then Hit/Expertise so builders land and feed the Oath Chain, then Crit (feeds Scarlet Champion's stacking Holy-damage buff and Scourgebane procs), then Haste for faster builder cycling, with Stamina/Resilience prioritized on PvP gear for the not-dying-when-focused goal.")
SetGear("Bloodmage", "Sanguine", "Caster-hybrid. The Bloodmage passive lets it wield Staves, at the cost of gutting physical damage, which barely matters since Sanguine's identity is spellcasting, not melee. Prioritize a Spell Power staff or an Int/Spirit one-hand+offhand over any melee stat stick. Stat priority: Spell Power (drives literally every damage and healing formula) > Spirit (talents convert it into bonus spell damage for Transgression's duration, and Cunning of Atherann scales your spell damage off Spirit and Stamina) > Stamina (survivability, and it also feeds Cunning of Atherann's spell-damage scaling) > Haste (faster casts/ticks means faster Rage and Thirst generation, and Dark Presence stacks more haste) > Crit (Reckless Abandon turns each Thirst stack into crit chance) > Hit (cap it so Vampiric Fang and your nukes land, though Atherann's Wickedness supplies some) > Expertise/Armor Pen (dead stats, this isn't a physical spec) > MP5 (irrelevant, the resource is Health/Rage, not mana) > Resilience (situational PvP layer once the core stats are covered).")
SetGear("Bloodmage", "Accursed", "Weapon: a melee weapon matters. Reave deals a chunk of Weapon Damage and your transformed kit is built around swinging, so a solid one- or two-hand is core to your sustain. Stat priority: this spec's formulas are hybrid (Veinburst scales Spell Power plus Attack Power, form abilities like Reave and Ravenous Strike scale Attack Power), so gear that gives both Attack Power and Spell Power outperforms gear that only gives one. Agility is your primary stat. Forbidden Power converts a share of it straight into spell crit and spell hit, so it double-dips for your damage and your lifesteal. After that: Crit (feeds Darkcasting and Ultra Instinct procs, and Killer Instinct's Rage-scaled crit on Veinburst/Reave), Haste (more transformed swings = more Ravenous Strike lifesteal ticks, plus Dark Frenzy's party haste), then Hit/Expertise, since landing Ravenous Strike and Reave reliably is core to your sustain. Armor Pen is a lower-priority physical-damage stat.")
SetGear("Bloodmage", "Eternal", "One-handed melee weapon for your transformed swings. Item armor is multiplied while Eternal Curse is up, with Thick Pelt stacking on top, so armor value on gear is worth far more to you than to a normal light-armor wearer. Stat priority: Stamina first (feeds Eternal Curse's own bonus, Vitality, and Enraging Wounds' Stamina-scaling leech), then Attack Power / Strength, since Ravenous Bite, Claw Sweep, Bloodfang Bite and Rotclaw all scale off it. Feral Strength also converts your Agility and Strength into extra Attack Power while Eternal Curse is active. Spell Power is secondary for the Shadow-damage side of your abilities, then Hit and Expertise for melee reliability. Crit next (feeds Enraging Wounds' melee-crit leech), then flat Armor and Resilience for PvP survivability, and Armor Pen situationally for your physical hits. MP5 is irrelevant since you run on Rage.")
SetGear("Bloodmage", "Fleshweaver", "The kit text doesn't spell out a base armor class, but the stat lines make the priority clear regardless of slot. Spirit is king: it directly scales nearly every heal (Blood Veil, Hemoglobe, Sanguine Mend) and Gift of Lana'thel converts it into spell power and spell hit rating. Then Spell Power (scales almost the whole healing/damage kit), then Stamina (survivability plus a direct scalar on Hemoglobe), then Attack Power (a slice of Blood Veil and your health-cost casts scale off it). Haste speeds up your Rage-building casts. Crit and Hit round out the caster side, and Hit is partly covered by the Spirit conversion. Resilience matters for the PvP-survivability goal. Weapon: itemize your weapon and off-hand for Spirit/Spell Power. Your output is Spirit/SP-driven healing, so there's no melee-stat weaving to chase.")
SetGear("Ranger", "Archery", "An Agility, light-armor DPS profile. Mainhand Bow or Crossbow is mandatory, since nearly every spender (Precision Shot, Hunting Shot, Serrated Shot, Brutal Shot, Incendiary Shot, Skullpiercer) is a ranged shot. Stat priority: Agility first (ranged attack power, crit) > Hit Rating to the ranged cap (every ability is a shot that can miss) > Crit Rating (feeds Archery Master's Advantage generation and, via Bleeding Edge, crittable Serrated Shot ticks) > Haste (Nimble converts Agility to ranged haste, and more shots per minute = more Advantage) > Stamina (load-bearing given zero self-heal). Armor Penetration is minor here. Corrosive Poison already ignores armor against Poisoned targets.")
SetGear("Ranger", "Brigand", "Dual Daggers are mandatory. Ravage, Assault and Viper's Bite explicitly require Daggers. Only Wild Strike, Flank and Skullpiercer merely require a melee weapon, and a polearm alternative scales via Ambuscade/Tip of the Spear/Polearm Craft, but losing Ravage/Assault/Viper's Bite isn't an option for the mainline build. An Agility, light-armor melee profile fits the kit. Stat priority: Agility first (feeds Attack Power and the Physical/Nature scaling running through every Brigand ability), then Hit/Expertise to land Assault/Ravage reliably and keep Advantage generation uninterrupted. Then Crit (feeds Highwayman's behind-the-target haste, Dice Games' Wild Strike/Assault crit, and Marked for Death's sub-35% stealth-ability procs) and Haste (more swings means faster Focus/Advantage generation via Banditry regen and the Ravager Wild Strike proc). Armor Penetration is a physical-damage multiplier, and Stamina gets prioritized on defensive slots given the total absence of self-healing.")
SetGear("Ranger", "Farstrider", "An Agility, light-armor profile. Primary weapon is a Bow or Crossbow. Skullpiercer, Whipvine Arrow, Woodland Arrow and Emerald Arrow, your whole finisher kit, all require it. Stat priority: Agility first (feeds ranged AP and the several Agility-scaled effects across the kit), then Hit/Expertise to land your shots and finishers reliably. Then Crit (fuels Advantage burst and crit-triggered Dream Flower/sustain procs, and Windrunner's Reach's bonus crit vs Undead/Beasts/Dragonkin), then Haste (faster Quick Shot cadence = faster Advantage generation and quicker Falconstrike transformations), with Stamina prioritized for the PvP survivability floor. Armor Penetration is low priority, since most of the kit's damage scales off AP/weapon damage or is Nature-typed, not armor.")
SetGear("Chronomancer", "Infinite", "Caster profile: caster-itemized gear, staff or 1H caster weapon plus off-hand. Keep a real wand equipped, since Timerend is your transformed wand cast. Stat priority leans on Spirit as the signature stat. Gift of the Infinite Dragonflight converts Spirit into both spell damage and spell hit, so Spirit sits near the top alongside Spell Power, which scales nearly every nuke and DoT. After that take Haste (shortens casts, feeds Hourglass of Eternity's haste procs and Melt Reality's tick rate) and enough Hit to land Chromatic Shard/Melt Reality/Discordance reliably, with Spirit already helping there via Gift of the Infinite Dragonflight. Then Crit for bigger DoT and Chromatic Shard hits. Warpstriker trims spell cost, so mana is rarely the ceiling. Spend leftover budget on Stamina/Resilience for PvP survivability given the spec's thin personal defensive kit.")
SetGear("Chronomancer", "Time", "Caster kit: staff (or 1H caster weapon + off-hand) for spell power. Stat priority: Spirit first. Sands of Life converts it DIRECTLY into healing power, and Through The Aeons boosts your Spirit-based mana regen, so it's your top throughput stat, not just sustain. Then Spell Power (heal/shield formulas scale off it), then Haste (shortens Epoch cast times and speeds your heal cadence), then Intellect and Crit roughly even and swappable to taste (Crit shaves Ripple's cooldown via A Ripple In Time and feeds Cadence of Time). This is pure healing, so there's no Hit/Expertise to itemize. Keep Spirit/MP5 high enough to survive the mana-hungry Aeon and shield kit. Given the PvP-forward goal, weight some Resilience into the mix, since this spec wins fights by surviving focus, not by topping meters.")
SetGear("Chronomancer", "Artificer", "Spirit is the signature stat. Artificer's Empowerment raises it and Wand Expert converts it to ranged attack power, so it scales almost the whole kit. But the stats experts chase first are the caps: hit and spell penetration. There are no hit talents in the tree and hit is scarce on Spirit-itemized gear, which makes it the hardest and most valuable stat to reach cap on. Spell penetration matters because your Arcane portions (Shatter Echo, Singularity Core, Decomposition, Arc Collision) are resisted by higher-level targets, and hitting the pen cap zeroes that out on raid bosses. Spell Power is overrated for this spec. Only a few abilities scale it and weakly, so treat roughly 100–200 SP as a floor rather than a priority. Your wand is a core damage stat-stick, not a slot-filler: Artificer's Wand, Singularity Core and Shatter Echo all read Ranged Weapon damage. Because Artificer's Wand has a static cast speed, you want the highest flat damage range, which means a slow wand, rather than the highest listed DPS. After the caps and Spirit, take Crit, then Haste. At 60, crafted and Worldforged pieces generally outclass heroic-dungeon gear. Mana is a non-issue once talented, so spend any leftover budget on Stamina/Resilience for PvP given the thin defensive kit.")
SetGear("Necromancer", "Death", "Caster kit with a staff or 1H + offhand. Every mechanic points to a pure Intellect caster. Stat priority: Intellect first, then Hit to cap, then Haste hard. Rotting Flesh lets Flesh to Worms' periodic damage scale with spell haste and Cycle of Death/Death Commander add more, so haste directly speeds your disease ticks and therefore your whole DoT-driven output. After that, Crit (Dark Harvester, Creeping Crypt and Plague Revenant all key off crit) and Spirit/MP5 to offset the mana costs on the utility layer. For PvP, weight Stamina and Resilience. With no self-heal or hard CC, your identity is surviving focus fire long enough for the disease ramp to matter, so raw HP pool matters as much as offense.")
SetGear("Necromancer", "Rime", "Caster kit: staff or 1H + offhand caster weapon, no melee weapon investment. Stat priority: Intellect first (Crown's Call and Lich Form scale your Frost damage off it, Ice Mastery converts Int to spell power, and Curse of the Lich boosts frost crit), then Hit to cap so your freezes and burst land, then flat Spell Power. Then Haste (Deathly Chill speeds Ice Barrage, and haste speeds casts and Runic Power generation), then Crit (feeds Permafrost/Soulfreeze proc chains and Frigidness/Frozen Power's crit-damage bonus vs Frozen targets). Keep Spirit/MP5 high enough to survive the constant %-of-base-mana costs. In PvP gear specifically, weight extra Stamina hard given the total absence of a self-heal. It's the only stat directly compensating for that gap.")
SetGear("Necromancer", "Animation", "Caster-weight gear built around Intellect first, since several pet formulas (Raise: Ghoul's leech, Bone Construct, the Command/Animate scaling) key off Int directly. After Int, prioritize Spell Power (Crypt Swarm, March of the Dead, and most pet-damage formulas scale off SP), then Haste (Graverobber/Mindless Fury shorten and reward your Raise/Animate/Command casts), then Crit and MP5/Spirit for sustained mana through long pull chains. Weapon: a spell power/Int caster main-hand + offhand. Melee stats like AP show up in a couple of pet formulas (Chomp, Raise: Ghoul's heal) but aren't worth itemizing for over caster stats. Carry enough Stamina to raise your effective HP floor and feed Sepulchral Might, which converts a share of your Raised minions' Stamina into spell damage.")
SetGear("Pyromancer", "Incineration", "Caster itemization built around Intellect and Spell Power. Use a wand/staff-or-dagger caster weapon setup. Stat priority: Spell Power > Hit (to cap, since most of the kit is a hard-cast landing DoTs/spenders) > Critical Strike (feeds Lighting the Fuse periodic crits, Wreath of Flames, and Flamecasting stacking) > Haste (compounds with Flamecasting for a snowballing cast-speed loop) > Intellect (mana pool, and Lighting the Fuse also turns Intellect into crit) > Spirit/MP5 (helps sustain casting) > Resilience once PvP-geared, since you're a squishy caster with no defensive cooldown and no heal.")
SetGear("Pyromancer", "Flameweaving", "Caster-healer: wand + staff (or wand + one-hand/off-hand). Stat priority: Spirit first (nearly every heal, including Ember Touch, Cinderheart and Kindle, scales directly off Spirit, Scorching Spirit/Spirit of Fire further amplify it, and Fiery Faith even converts Spirit into crit), then Spell Power (scales both the healing and damage side of the same spells). Then Haste (feeds cast-time reduction on your heals and Flare Bolt and stacks with Flamecasting), then Crit (many talents key off crit: it triggers Inferno, Shielded by Flames absorbs, and Burning Passion Heat) and MP5 for sustained fights. Pick up Hit if you're leaning on Flare Bolt/Lava Shard damage while leveling solo. Stack Resilience for BG survivability once you're geared past the leveling curve.")
SetGear("Pyromancer", "Draconic", "Caster. Weapon: staff (or wand/offhand caster stick) with the highest Spell Power roll available, since it scales Flare Bolt, Destroyer's Maw, Echo of Nozdormu and Death From Above. Stat priority: Intellect first (Draconic Aspect and the Draconic passives convert Intellect into spell damage, crit, and hit, plus mana pool), then Spell Power, then Hit (to cap, since the kit is hard-cast), then Haste (faster Flare Bolt casts = faster Heat/Ember generation), then Crit. Spirit/MP5 still helps on long fights, though Ashen Skin (in-combat regen + mana from your own damage) and Essence of Malygos ease the mana crunch more than raw regen does. Pick up Stamina/Resilience for PvP given the total absence of a defensive cooldown. You need the raw HP buffer, because nothing else will save you reactively.")
SetGear("Cultist", "Godblade", "Weapon: a two-handed melee weapon. The whole melee kit (Voidforged Edge, Netherstrike, Obliteration, Abyssal Cleave) keys off weapon damage and melee range, so itemize for a big 2H. Stat priority: Strength first. It double-dips via Void Strength, increasing your Shadow spell damage and spell hit by a portion of Strength, on top of feeding Attack Power for your weapon-damage abilities, which makes it the single best stat in the kit. Then enough Hit/Expertise to stop missing or getting parried in melee. Then Crit (feeds Twilight's Call's Insanity refund on Obliteration crits, the Shadow of the Void crit buff, and Encroaching Presence's cooldown reduction) and Haste for both melee and Shadow-spell scaling. Then Stamina for survivability. Intellect/Spell Power and Spirit are secondary. Don't chase them over Strength.")
SetGear("Cultist", "Corruption", "Caster armor with a caster weapon (staff or 1H + off-hand). This is a pure ranged spec, so there's no reason to carry a melee weapon. Stat priority: Intellect (mana pool, and via the Level 20 Dark Magician passive it converts into spell power) > Spell Power (the dominant term in nearly every damage formula in the kit) > Haste (accelerates the Horrorbolt/Wrath loop and speeds your periodic damage) > Crit (feeds Dark Magician's crit-damage bonus and Feeding Darkness's crit chance) > Hit (needed early to land Horrorbolt and Darkwither reliably) > Spirit/MP5 as a low-priority mana-sustain stat once your rotation stabilizes. For PvP, also value Stamina and some Resilience given how exploitable your cast times are under focus.")
SetGear("Cultist", "Dreadnought", "One-hand weapon and shield. The shield is your engine: block generates Insanity and feeds Void-Enhanced Shield/block-value scaling and the critical-block procs, so itemize for a strong shield alongside a solid 1H. Stat priority: Strength first (it feeds Attack Power for your weapon strikes and, via Strength of the Sha, converts into Shadow spell damage), then Stamina (survivability, and it scales your absorbs), then block/defense rating (it fuels Inner Darkness Insanity generation, Void Strikes, and the critical-block procs). Then enough Hit/Expertise to reliably land Void Strikes and Twilight Shieldtoss, then Intellect/MP5 for mana-pool headroom since every ability costs a % of base mana, then Crit/Haste as filler. For PvP, value Defense/Resilience specifically, since your kit's magic mitigation doesn't help against crit-heavy physical burst.")
SetGear("Cultist", "Heretic", "Crit is the stat that pays twice, and it is why this spec gears unlike any other healer. Blessing of Yogg-Saron (Level 50 passive) converts spell critical strike rating into attack power at 3:1, and attack power is what scales your primary heal. Black Blood, the heal-over-time from Malevolence, scales off attack power alone with no spell power term at all. Dark Prophet then lets Black Blood critically heal, so crit feeds the same heal from both ends. Void Power adds healing power from your main-hand weapon damage, which favours a big, slow 2H. A main Heretic's priority runs Critical Strike > Strength/Attack Power > Spell Power > Intellect > Agility > Stamina. Spell power is still a real secondary rather than a dump stat: Void Shield and Forbidden Ritual scale off it alone, and Dark Veil and Blade of the Empire scale off both. Intellect still governs how often you have to stop and Sanity Tap. What you do not need is hit or expertise. Shadow Training (Level 20 passive) makes you unable to miss and unable to be dodged or parried, which is a built-in cap. Note also that Empire Commander stacks with a Shadow Words-buffed Whispers of N'zoth for roughly 24% additional primary stats, so each point of Strength or Intellect you gear is worth about 1.24. Weapon: 2H (polearm, staff, 2H axe/mace/sword) to unlock Malevolence and satisfy Blade of the Empire's melee requirement. 1H plus off-hand loses Malevolence entirely.")
SetGear("Starcaller", "Moon Guard", "Weapon + shield is mandatory, not a preference. Blanket of Stars requires a shield, and the spec's block payoffs all key off it, so a two-hander forfeits the mitigation model outright. Prioritise avoidance and block first (Block/Dodge/Parry rating), because that is what carries you through the window when the Aegis is down. Then Strength, which is unusually valuable here: it feeds Block Value, so it is both mitigation per block and more Starburst damage. Then Stamina for a bigger pool to be healed through, then Intellect. Mana is not a throughput stat you can ignore, since abilities scale off your maximum mana. Defense is worth real investment. It raises Dodge/Block/Parry together, and there is no crit-reduction talent in this tree, so gear has to cover crit avoidance. Pick up Hit where you can, since it noticeably smooths threat. Haste helps by applying Scattered Stars faster. Plate with Strength/Spell Power/Defense is the profile to look for.")
SetGear("Starcaller", "Sentinel", "Sentinel straddles caster and physical stat lines. Its own tooltips scale off Spell Power, (Ranged) Attack Power and Intellect simultaneously, with Explosive Moonlight even converting Intellect into ranged attack power and hit, and Aspect of the Huntress draining mana off auto-attacks. It is a pure ranged spec built around a ranged weapon (Moon Arrow/Huntress Shot/Starfire Shot/Trueshot), with no melee-weapon abilities in the kit. Stat priority: Intellect first (mana pool plus feeds several damage formulas and, via Explosive Moonlight, ranged attack power and hit directly), Spell Power second, Haste third (Huntress Training turns Intellect into haste and shrinks the Starfire Shot/Trueshot cast/cooldown class). Crit is fourth (feeds Eye of Elune and the Tyrande's Guidance/Training bonus crit damage on Starfire Shot), then Hit/Expertise toward the cap, with Spirit/MP5 low since combat sustains mana on its own. Weight Resilience given how much of its PvP survival rests on not being burst down before its slows and mobility are back up. For the leveling/BG spell-archer build specifically, treat Spell Power as the primary damage stat, since Lunar Lance and your Scattered-Star payoffs scale directly off it, not off bow/weapon damage, with Intellect close behind for the mana pool several tooltips also scale from.")
SetGear("Starcaller", "Moon Priest", "Uses a melee weapon (one- or two-hand) as its weapon slot, but the mana-regen engine runs off its ranged attacks. Moon Arrow and Huntress Shot both feed the mana-return and Scattered-Star loop. Stat priority: Intellect first (bigger mana pool directly scales heals that cost and scale off percentage max mana, plus spell power), Spirit close behind (MP5 to offset the constant percentage-mana drains). Then Spell Power and Haste (GCD-capped heal weaving, and Rapid Cycle's Lunar-Phase ranged haste). Crit is valued for Lunar Phase generation (Moon Gazing) and the Enchanted Water/Enchanted Stream crit-healing bonuses on Touch of Moonlight/Hand of Elune/Moonflow. Pick up Resilience once mana and haste breakpoints are comfortable. Armor type itself matters less than hitting these rolls.")
SetGear("Starcaller", "Warden", "Requires a melee weapon (Celestial Strike, Starsunder, Astral Blade, Warden's Blade all need it) and uses Sentinel Glaive as its thrown ranged tool. A spell-power staff is often the best weapon here even though it reads as a caster item. Astral Blade and Umbral Blade take no weapon damage and scale off Spell Power (and max mana), so a staff's Spell Power/Intellect can outvalue the weapon DPS of swords, especially for the burst/one-shot build. Wear whatever base armor proficiency Starcaller is assigned. Stat priority: Intellect first (feeds the max-mana damage scaling on Starsunder/Astral Blade and the mana pool, and doubles as crit and expertise via Maiev's Discipline), then Spell Power and weapon DPS/Attack Power (both feed the hybrid damage formulas directly). Then Haste (Energy/cast speed) and Crit (feeds the Shadowsong's Mandate to Warden's Blade proc chain, and Astral Blessing's crit-driven Warden's Blade cooldown reduction), then Spirit/MP5 for out-of-combat mana recovery given how much mana the burst kit drains. Hit is partly covered by Moonlit Impaler's Arcane-hit bonus, so gear toward softcap rather than overcapping.")
SetGear("Sun Cleric", "Piety", "Pure caster: a staff or 1H + off-hand itemized for spell power and Intellect. There is no melee weapon strike in this spec, so weapon DPS is irrelevant. Stat scaling is Intellect-first. Struck by the Sun converts Intellect into spell hit and boosts your Holy/Fire spell damage, and Photosynthetic/Learning Light drive your haste, so Intellect is the primary stat, not weapon damage. Priority: Intellect > Spell Power > Haste (faster casts, Solar Power ticks, and cooldowns) > Crit (feeds the crit-scaling passives like Pious and Wrath of God) > Spell Hit (until capped, so your nukes land) > Spirit/MP5 (keeps the percentage-cost nukes fed) > Stamina, weighting Resilience up specifically for the BG/PvP goal. Strength and Expertise are dead stats. There is no melee side to the kit.")
SetGear("Sun Cleric", "Blessings", "Weapon: itemize as a caster healer. There is no melee/Rage loop in this spec, so weapon choice is about spell power and Intellect, not weapon damage. Armor: Intellect-based healer itemization. Sun Worship and Sun Strength both convert Intellect into healing power, and Sun Worship also into spell haste, so Intellect is your primary stat. Stat priority: Intellect first (feeds healing power, haste, crit), then Haste (faster casts, quicker Solar Power/Dawn cadence). Then Crit (feeds the Cultivate Divinity / Hope / The Redeemer crit-heal payoffs and guarantees Radiant Cascade crits via Sun Strength), then Spirit/MP5 (your cast-time heals still need mana sustain), then Resilience for PvP. Strength and Armor Penetration are effectively dead stats, since there is no melee side to the kit.")
SetGear("Sun Cleric", "Valkyrie", "Wields two-handers, or dual-wields one-handers with Valkyr's Grip boosting off-hand damage. Stat priority: Strength first. Valorous Champion converts Strength into attack power and spell hit, and Impartial boosts Strength and max mana, so weapon DPS and Strength drive the whole kit at once. Then enough Hit/Expertise to land your melee-connect abilities, since Glorious Execution and Justice all need to land to generate Solar Power and refund mana. Then Haste (faster autos and swings mean faster Solar Power generation), then Crit (feeds Gift of the Sun and the crit-scaling synergies) and flat Attack Power. Champion of the Sun, Valorous Champion and Valkyr's Calling all carry AP coefficients, so weapon DPS matters a lot. For PvP, value Resilience to survive the windows outside Valkyr's Calling, plus a little Spirit/MP5 for mana between Glorious Execution refunds.")
SetGear("Sun Cleric", "Seraphim", "Strength/Stamina block tank with a one-handed melee weapon and a Shield. Dawnbreak and the Gavel strikes scale off your weapon and block value, and Seraphic Bulwark and the block toolkit all require a Shield. Stat priority: Strength first. It feeds attack power, and via Holy Strength converts into spell power for your Holy/Fire strikes, while Sun-Touched Armor turns Strength into Armor. Then Stamina for raw survivability, compounded by Sun-Touched Armor's Stamina bonus. Then Intellect (Clarity of the Heavens turns it into block value and Solar Discernment into crit/expertise), then enough Hit/Expertise to land Justicar's Wrath / Dawnbreak, then Crit (feeds Sun Warrior's Guidance, Bastion of Hope, and Sun Strider) and Haste for the Holy/Fire strikes. Resilience is weighted heavily for the PvP-first goal, with Defense/MP5 as rounding stats.")
SetGear("Tinker", "Demolition", "Ranged weapon: a Gun or Rifle. Primary stats are Agility and Intellect, and Bomb Squad even converts a share of your Agility into Fire spell power, so Agility does double duty as your damage stat and part of your spellpower. Stat priority: ranged Hit first (Incendiary Bullets already buffs your hit chance, but landing Scrap Shot and Rocket Launcher reliably matters most). Then Crit (feeds Boom Hour, Buster Scope, Short Fuse, and the mana refund on Explosives Expert), then Haste (shrinks GCD and speeds your Scrap Shot weave). Then a mix of Attack Power and Spell Power, since your scaling reads off ranged attack power and Fire spell power together (Bomb Toss, Rocket Launcher, Spider Bomb, Hyperblast Barrage). Don't dump pure Spirit/mana-regen gear. Explosives Expert refunds mana on crit, so crit-heavy offense sustains your bar better than raw regen.")
SetGear("Tinker", "Invention", "Kit uses a ranged weapon (a gun), and Repair Shot literally fires a Round from it, but there's no armor class specified. Gear as a light-armor ranged caster. Stat priority: Intellect first (mana pool plus Scientific Nature's conversion of Intellect into healing power and crit rating) > Spirit/MP5 (mana regen, since heavy percent-of-base costs run throughout) > Haste (faster Repair Shot cast and Nanobot tick rate) > Crit (feeds Eureka!, Field Medic, Emergency Circumvented and the crit-heal talents) > Spell Power. Repair Shot's formula includes a small attack-power term, so a sliver of AP scaling exists, but it isn't worth gearing over the healing stats.")
SetGear("Tinker", "Mechanics", "Uses a caster weapon (staff, or a 1H plus off-hand) alongside a gun for Scrap Shot. Mechanics has no melee-weapon requirement, so keep your caster weapon and gun current. Stat priority: Agility/Attack Power and Intellect are both primary, since your ranged and Mechsuit damage read off ranged attack power (Combustion, Activate Jets) while mana and much of the kit lean on Intellect. Then Crit (Cogmaster converts ranged crits into Scrap and boosts crit chance, and Arclight Adept amps Mechsuit crit damage) and Haste (faster casts and more Mechsuit uptime). Carry enough Spirit/MP5 or a deep mana pool to absorb the heavy percentage-of-base-mana costs stacked across summons and abilities. Running dry mid-fight is a real failure mode. The Mechsuit's own armor (Defensive Utility) and Regeneration Enhancement mana refund ease the pressure while transformed.")
SetGear("Venomancer", "Rot", "The class is a caster shapeshifter, so gear toward caster-itemized gear. Weapon: a caster stat-stick (staff or 1H + off-hand) for Intellect/Spell Power. Stat priority: Intellect first and by a wide margin, since Shadra's Gift converts Intellect into spell damage and haste, so itemization should chase Int hard. Then Haste (periodic tick rate), then Spell Power/Crit as secondaries (Rotpriest and Rotting Away reward crit), then Spirit/MP5 for regen since nearly everything costs a percentage of base mana. Hit is needed to land Sepsis Bloom and your DoTs reliably, because a resisted disorient is a wasted window. Add Resilience for PvP survivability given how thin the personal defensive kit is.")
SetGear("Venomancer", "Stalking", "Intellect is a strong stat here. Prowler converts Intellect into spell damage and hit, and several hard-hitting abilities (Facemelter, Withering Venom, Nerubian Sting) scale off Spell Power in their tooltip math. But auto-attacks and Vulnerability's proc uptime matter, so Agility and haste have real value too. Priority: Intellect > Spell Power > Hit > Crit > Haste > MP5/Spirit to keep the utility-mana layer from running dry, plus Stamina/Armor/Resilience since it fights entirely at melee range and will get focused. Weapon: a caster weapon (staff or 1H + off-hand) for Intellect/Spell Power. Wear whichever caster-itemized armor in your pool grants the most Intellect/Stamina.")
SetGear("Venomancer", "Fortitude", "Take a caster weapon (staff or 1H + off-hand) with Intellect and Stamina. Auto-attacks and on-hit still matter. Chitin Rush hits, Exposed Flesh's rage-on-hit proc and Pendo's Charm's rage-from-damage all key off landing hits. Stat priority: Stamina first (the whole kit is built around soaking hits to fuel Exposed Flesh/Rage, and Chitin Rush scales off Stamina). Then a mix of Attack Power and Spell Power on the weapon/trinkets, since Chitin Rush, Carapace Crash, Hivebreak and Venomtip all scale off both (Poisonous even turns attack power into spell damage), then Agility for crit/dodge. Stack bonus Armor from itemization (Enchanted Chitin amplifies your Armor contribution and Reinforced Exoskeleton adds max health and dodge), and pick up Resilience/Defense where available for PvP survivability. Avoid stacking pure Spell Power, since it under-uses the Stamina/avoidance side of the kit that this spec depends on to function.")
SetGear("Venomancer", "Vizier", "Wear caster-itemized gear, since Vizier itself never melees. Your weapon should be a caster stat-stick (staff or 1H + off-hand), because the Vizier ability list has essentially no melee. Stat priority: Intellect first (feeds mana pool and, via Spiritual Healing, both crit rating and healing power). Then Haste (Vizier Form lets your HoT effects benefit from spell haste, tightening the heal loop), then Spirit/MP5 (this kit runs on percentage-of-base-mana heals and needs real regen to avoid going dry), then Spell Power, then Crit. You need little to no Hit, since the spec has effectively no offensive casts beyond Serpent's Fang and Fangbinder makes that unable to miss. Prioritize Resilience on PvP gear given how thin the personal defensive kit is.")
SetGear("Reaper", "Harvest", "Weapon: a two-hander is mandatory. Crow's Harvest, Slaughter and Doomrend are your core 2H rotational abilities (Polearms, Staves, Two-Handed Axes, Two-Handed Maces or Two-Handed Swords), so there is no 1H/shield or dual-wield build for this kit. Reap separately just requires a melee weapon, which the 2H already satisfies. Armor: the kit doesn't state an armor proficiency directly, but given the heavy Strength scaling (Executioner converts Strength into crit and armor pen) and the hybrid AP+SP damage formulas (Doomrend and the Shadow half of your kit scale off both), gear as a Strength-primary melee/Shadow hybrid. Itemize it like a Death Knight: Strength gear with Spell Power as a valued secondary rather than a separate caster set. Stat priority: Strength (drives AP, which drives both damage and the healing that scales off it) > Hit/Expertise to caps (misses on Reap/Doomrend/Slaughter/Crow's Harvest mean no damage AND no leech) > Spell Power (boosts the Shadow half of every hybrid formula) > Crit and Haste roughly even (Crit feeds Souls for the Slaughter, Blood Knight's Doomrend refunds, and Executioner, while Haste explicitly speeds up the Darkrend Scythe bleed tick rate and your basic swing/Reap uptime, and Sanguine Harvester already grants some) > Stamina and Resilience for PvP survivability margin.")
SetGear("Reaper", "Soul", "Melee weapon-damage gear built around dual one-handed weapons. Dirge strikes with both weapons and hits harder with a dagger equipped, and Soulforged Weaponry rewards dual-wielding with off-hand damage and free Murders. Stat priority: weapon damage/Attack Power first (Reap, Dirge, Wraithblade and the fragment-generation loop all scale off weapon damage and AP, and several abilities list explicit AP coefficients alongside Spell Power). Spell Power sits close behind, since Deathchaser, Soulrend, Reliquary of the Lost and Spectre Stride all carry SP coefficients too. This is a hybrid AP/SP scaler, not a pure Attack Power melee. After that: Haste (more autos means more fragment generation and Soulforged Weaponry procs), Crit (Soul Generator's crit-triggered Runic Power and extra Reaped Souls, Spirit Chaser's crit boost on Reap/Deathchaser/Wraithblade), then enough Hit/Expertise (Mark of Death already grants some) to land your melee kit reliably. Stamina for the raw HP pool behind Spiritual Reflexes' 35% threshold. Armor: whatever armor class the Reaper is restricted to on this realm, itemized for Str/Sta over pure Spirit-caster pieces.")
SetGear("Reaper", "Domination", "2H weapon is the spec's weapon: Polearm, Staff, 2H Axe, 2H Mace or 2H Sword, driving the weapon-damage component of Reap, Dreadwake and Requiem. This is a heavy bruiser, and Dreadknight boosts your Armor contribution from your gear. Stat priority: Strength first (drives AP for Reap/Dreadwake's weapon-damage component, and Behemoth converts it into Armor penetration while Dark Soul turns Armor pen rating into Stamina), Stamina essentially tied for second (feeds Spectral Warden's shield size, Behemoth's stamina scaling, and Soul Splinters' stamina-scaled eruption). Then Spell Power close behind (scales the Frost/Shadow half of Dreadwake, Requiem, and Deathwind). Take enough Hit/Expertise (Dark Soldier already grants some hit) to land Reap/Dreadwake/Requiem reliably, plus moderate Crit (Final Requiem crits harder below 20% HP). Don't sleep on Defense/parry rating: Soul Slip turns your own avoided attacks directly into Soul Fragments and Empyrean Fortitude generates Runic Power on parry, an unusual payoff for avoidance stats. Haste is low priority. Resilience is worth stacking once geared, since the whole spec's identity is refusing to die.")
SetGear("Primalist", "Wildwalker", "Weapon: a melee weapon is required. Wildclaw, Totemic Smash, Primal Shred and Rylak's Bite all need one. Primal Weapons (level 20) grants a bonus based on whether you run one-handed or two-handed. The 2H route pairs well with a kit where nearly every hit is a %-weapon-damage nuke, while a 1H build leans on crit-triggered effects. Stat priority: Strength/AP first (everything scales off weapon damage and AP coefficients), then Hit/Expertise to reliably land Totemic Smash and your strikes (Raptor Talons adds expertise). Then Crit hard (Legacy of Rexxar, Rexxar's Might, Lacerations, Torn to Shreds and Sharpened Claws all trigger on crit, and this is where the bleed-and-proc engine comes from). Then Haste (more Wildclaw/Totemic Smash swings = more rage and more procs). Prioritize Stamina/Armor/Resilience for BG survivability, alongside a bit of Spell Power, since a few formulas partially scale off it.")
SetGear("Primalist", "Geomancy", "Caster weapon (staff, or one-hand plus off-hand). Stat priority: Intellect first (it drives spell power, the mana pool, and, via Crushing the Earth converting armor penetration to spell power and Stoneskin adding armor from Intellect, much of both your damage and durability) > Hit so Geode Barrage and your Seismic nukes land clean > Haste and Crit (Haste shortens your ramp and cast-heavy loop, while Crit feeds Volcanic Blast's fire splash and, at level 50, Therazane's Blessing lets your Seismic periodic damage crit) > Armor Penetration (Crushing the Earth turns it into 50% of its value as spell power, so it double-dips as a caster stat here) > Spirit/MP5 for mana sustain in long fights > Stamina/Resilience situationally for pure PvP survivability. The Seismic/Geode core deals PHYSICAL damage, so Armor Penetration is a scaling stat here. You get most of it for free from Intellect (Cave Dweller), and Crushing the Earth converts half of it back into spell power, so you rarely stack it directly. NEVER gear Spell Penetration. Your damage is physical, so it does nothing. Crit is a high priority (Earthshaping amplifies your crit damage and Terrasurge auto-crits under Seismic Tremor). Avoid Strength/parry/block melee gear. Itemize Intellect / Spell Power / Crit.")
SetGear("Primalist", "Grovekeeper", "The kit's melee-hybrid passives (Grove Training's melee/heal Aftershock proc, Hammer of Life off melee swings, Battleweaver's heal-into-melee-haste, Nature's Fury's auto-attack mana return) point to a melee-caster hybrid loadout. Equip a caster weapon. Gear as a hybrid caster/melee healer rather than a pure caster. Stat priority: Intellect and Spirit/MP5 first, since most of the utility/protection kit is mana-gated and needs to not go dry. Then Spell Power and Attack Power roughly evenly, since core heals scale off both (Tears of the Earthmother, Spirit Charge, Seismic Wave, Sacred Grove all have SP and/or AP coefficients). Then Haste (helps cast times and gets you to your next Hammer of Life-eligible swing faster), then Crit (feeds Infusion of Neptulon's crit-heal proc and Primordial Earth's crit-summoned Spirits of Life). For the PvP-survival goal, weight Stamina/Resilience/Defense higher than a pure PvE build would.")
SetGear("Primalist", "Mountain King", "Weapon is non-negotiable: melee weapons, dual-wield or one-hand, since Rock Barrier, Quake, Mountain Fury, Seismic Smash and Mountain Hammer are all melee tools. Stone Soldier explicitly rewards an off-hand weapon, so a dual-wield build fits the kit. Stat priority: Stamina and Strength are both top-tier. Stamina because Mountain Fury and Seismic Smash scale directly off it and raw HP is the core of the don't-die-when-focused goal, with no self-heal in the kit. Strength because it drives Attack Power and, via King of the Mountain, converts into parry/dodge/haste rating. Then Armor/Defense (stacks with Rock Barrier and Boon of the Turtle for a real physical mitigation floor), then Hit/Expertise to a comfortable threshold so Quake, melee and the Seismic family reliably connect and keep generating rage, then Crit for extra rage-per-swing and burst. Spell Power only shows up as a minor multiplier on Mountain Fury/Mountain Hammer, so don't itemize for it over Str/Sta. For the PvP-focused goal, trade some Crit/Haste for Resilience once your rage generation and damage feel comfortable. Your magic-damage weakness means physical anti-focus stats matter more than raw offense.")
SetGear("Runemaster", "Glyphic", "Caster itemization: Intellect/Spell Power first (mana pool plus Wizardry's Intellect scaling and Focusing Crystals' magic-damage boost), then Haste (feeds glyph generation speed and the Runeslinger/Runes of Quickness haste procs). Then Crit (synergizes with Eye of the Beholder and Arcane Student's guaranteed Glyphic Ruin crit under Glyphic Overload). Then Spirit (Ley Magician turns Spirit into spell damage and hit, Concentrated Magic reduces pushback and boosts Spirit, and Focusing Crystals carries part of your regen into combat), then enough Hit to land Glyphic Ruin/Silencing Rune reliably. Some damage formulas in this spec (Thaumaturgy) carry a small Attack Power term alongside Spell Power, so don't fully dump a weapon slot's AP if the designated caster weapon offers it. Int/SP remains the primary lever. Pick up some Resilience for PvP survivability given the total lack of self-healing and any damage-reduction cooldown.")
SetGear("Runemaster", "Engravement", "Weapon: dual-wield TWO fast one-handed melee weapons. Weapon Engravings and Fist of the Ancients proc elemental damage off your autoattacks and hits, so swing speed, plus a second weapon via Fists of Power, drives proc frequency far more than raw weapon damage. Agility-based hybrid. Stat priority: Agility first (Primordial Strength turns Agility into spell hit/hit and converts attack power into spell damage, feeding the elemental engraving procs) alongside Attack Power. Then Haste and Critical Strike (more autoattacks and bigger engraving procs, and Engraved and Ready boosts their crit), then enough Hit/Expertise to land hits and specials. The engraving damage is elemental/magic, so ARMOR PENETRATION does nothing. Don't stack it. Value Spell (elemental) Penetration instead, to push that magic damage through resistances, which matters most in PvP. Agility + spell pen is hard to itemize together, so spell-pen PvP gems help. Example setup: two fast one-handers (e.g. Flurry Axe) plus an on-hit/haste trinket like Hand of Justice.")
SetGear("Runemaster", "Riftblade", "Two-handed melee, Agility-based. Stat priority: Agility first (Elemental Assassin turns Agility into spell damage, crit, and hit for your elemental strikes, on top of its normal melee value), then Stamina for the 1vX EHP goal. Then Haste and Crit (more Runeblade procs, more strike throughput, and Runic Invocation/Unbound Energy crit synergy), then enough Hit/Expertise that Runeblade and your strikes aren't whiffing or getting parried. The kit carries a mana cost on its spells even as a melee, so a little Spirit/regen isn't wasted, but Agility remains the primary lever. Spellblade adds a flat Agility/Intellect boost, so gear that carries some Intellect isn't dead weight. Don't itemize around it over Agility.")
