GuideProfiles.research.loadedProfiles = 0
for _, profile in ipairs(GuideProfiles.profiles or {}) do
    if profile.research then
        GuideProfiles.research.loadedProfiles =
            GuideProfiles.research.loadedProfiles + 1
    end
end
